@layer properties, theme, base, components, utilities;

@layer components {
  /* Do not set `display` here. The user agent hides `dialog:not([open])`, and an
     author `display` would override that and leave a closed dialog on the page. */
  .tesso-dialog {
    padding: 0;
    border: none;
    background: transparent;
    color: inherit;
  }

  .tesso-dialog[open] {
    display: grid;
    place-items: center;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    margin: 0;
    padding: 1rem;
  }

  .tesso-dialog::backdrop {
    background: color-mix(in oklch, var(--foreground) 40%, transparent);
  }

  .tesso-dialog-panel {
    position: relative;
    width: min(100%, 30rem);
    max-height: calc(100vh - 2rem);
    overflow: auto;
    padding: 1.5rem;
    background: var(--popover);
    color: var(--popover-foreground);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: 0 0.75rem 2rem oklch(0% 0 0 / 0.18);
  }

  .tesso-dialog-title {
    margin: 0;
    padding-right: 3rem;
    font-size: 1.25rem;
    font-weight: 600;
    line-height: 1.25;
  }

  .tesso-dialog-description {
    margin: 0.5rem 0 0;
    color: var(--muted-foreground);
    font: 400 0.875rem/1.5 system-ui, sans-serif;
  }

  .tesso-dialog-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
  }

  .tesso-dialog-footer {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 1rem;
  }

  .tesso-dialog-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
  }

  .tesso-dialog-title[hidden],
  .tesso-dialog-description[hidden],
  .tesso-dialog-body:empty,
  .tesso-dialog-footer:empty {
    display: none;
  }

  html.tesso-dialog-open,
  html.tesso-dialog-open body {
    overflow: hidden;
  }
}
